import { Logger } from '@nestjs/common';
import { getDocument, listDocumentKeys } from '../../utils/aws/s3.js';

/**
 * One of the accounts a customer has been onboarded onto.
 */
export class OnboardedCustomerAccount {
    /**
     * The AWS account the customer's workload runs in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * True when the account only ever runs this customer's workload, so every
     * metered resource inside it belongs to them no matter how it is tagged.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record a business keeps in its metering bucket.
 * These records are the only source of truth for who may be billed for usage
 * found in an account.
 */
export class CustomerOnboardingRecord {
    private static readonly logger = new Logger(CustomerOnboardingRecord.name);
    public customerId: string;
    public displayName?: string;
    public accounts: Array<OnboardedCustomerAccount>;

    /**
     * Reads every onboarding record stored under the prefix. Records that cannot
     * be read or that carry no customer id are skipped rather than failing the
     * whole sweep, they simply cannot make usage billable.
     */
    static async loadAll(bucket: string, prefix: string): Promise<Array<CustomerOnboardingRecord>> {
        if (!bucket || !prefix) {
            CustomerOnboardingRecord.logger.warn(
                'No customer onboarding record location configured, no usage can be attributed',
            );
            return [];
        }
        const keys = await listDocumentKeys(bucket, prefix);
        const records = await Promise.all(
            keys.map(async (key) => {
                try {
                    return await getDocument<CustomerOnboardingRecord>(bucket, key);
                } catch (e) {
                    CustomerOnboardingRecord.logger.error(`Couldn't read onboarding record ${key}`, e);
                    return undefined;
                }
            }),
        );
        return records.filter((record) => record?.customerId);
    }
}

/**
 * How an account's metered usage may be attributed to customers.
 */
export class AccountTenancy {
    /**
     * The customers genuinely onboarded for the account, the only ones its
     * usage may be billed to.
     */
    public customerIds: Array<string> = [];
    /**
     * Set when the account is dedicated to a single customer.
     */
    public dedicatedTo?: string;
}

/**
 * Turns the onboarding records into a per account view of who may be billed.
 */
export const buildAccountTenancy = (
    records: Array<CustomerOnboardingRecord>,
): Record<string, AccountTenancy> => {
    const tenancy: Record<string, AccountTenancy> = {};
    const dedicatedClaims: Record<string, Array<string>> = {};
    records.forEach(({ customerId, accounts }) => {
        (accounts ?? []).forEach((account) => {
            const accountId = typeof account === 'string' ? account : account?.accountId;
            if (!accountId) {
                return;
            }
            const entry = tenancy[accountId] ?? new AccountTenancy();
            if (!entry.customerIds.includes(customerId)) {
                entry.customerIds.push(customerId);
            }
            tenancy[accountId] = entry;
            if (typeof account !== 'string' && account?.dedicated) {
                dedicatedClaims[accountId] = (dedicatedClaims[accountId] ?? []).concat(customerId);
            }
        });
    });
    Object.keys(dedicatedClaims).forEach((accountId) => {
        const claims = dedicatedClaims[accountId];
        if (claims.length === 1) {
            tenancy[accountId].dedicatedTo = claims[0];
        } else {
            // More than one customer claiming the same account cannot be a
            // dedicated account, treat it as shared instead of guessing.
            CustomerOnboardingRecord.logger.warn(
                `Account ${accountId} is claimed as dedicated by ${claims.length} customers, treating it as shared`,
            );
        }
    });
    Object.keys(tenancy).forEach((accountId) => {
        tenancy[accountId].customerIds.sort();
    });
    return tenancy;
};
