import { OnQueueFailed, Process, Processor } from '@nestjs/bull';
import { infrastructureType } from '../../dimensions/dto/create-dimension.dto.js';
import { Job } from 'bull';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { MeteredAccount, MeteringRegistry } from '../../onboarding/entities/meteringAccounts.entity.js';
import {
    AccountTenancy,
    CustomerOnboardingRecord,
    buildAccountTenancy,
} from '../../onboarding/entities/customerOnboarding.entity.js';

const RUNNING_TIME_INCREMENT = 0.08333333; // TODO: make this dynamic

export type MeteredInstance = {
    accountId: string;
    instanceId: string;
    instanceType: string;
    region: string;
    tags: Record<string, string>;
};

/**
 * A slice of one instance's running time owed to a single customer.
 */
export type InstanceAttribution = {
    customerId: string;
    /**
     * Fraction of the instance's running time this customer carries, tenants
     * sharing an account split it evenly.
     */
    share: number;
};

@Processor('scheduler_queue')
export class Ec2InstanceDataGathererService {
    private static readonly logger = new Logger(Ec2InstanceDataGathererService.name);
    constructor() {}

    @Process(infrastructureType.instanceRunningTime)
    async readOperationJob({ data: { scheduleParameters, businessID, subject, rate } }: Job<SchedulerEntity>) {
        if (!('registryBucket' in scheduleParameters)) {
            throw new BadRequestException('Metering registry location not found');
        }
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        const { registryBucket, registryKey, dimensionId } = scheduleParameters;
        Ec2InstanceDataGathererService.logger.log(
            'Processing Automated Instance Uptime gathering event, logging inputs',
            JSON.stringify({
                rate,
                businessID,
                registryBucket,
                subject,
            }),
        );
        const measurements = await this.gatherUsage({ businessID, dimensionId, registryBucket, registryKey });
        measurements.forEach((entity) => StandardMeasurementEntity.publish(entity));
        Ec2InstanceDataGathererService.logger.log('Finished collecting EC2 instance running time data');
    }

    /**
     * Sweeps every account the business has onboarded and returns one usage
     * measurement per customer for the dimension being metered.
     *
     * Attribution follows the onboarding records kept beside the account list:
     * usage in an account dedicated to a single customer is always that
     * customer's, usage in a shared account is split evenly between the tenants
     * its tags name that are genuinely onboarded for the account, and anything
     * that cannot be placed on an onboarded customer is left off the bill.
     */
    async gatherUsage({
        businessID,
        dimensionId,
        registryBucket,
        registryKey,
    }: {
        businessID: string;
        dimensionId: string;
        registryBucket: string;
        registryKey: string;
    }): Promise<Array<StandardMeasurementEntity>> {
        const registry = await MeteringRegistry.load(registryBucket, registryKey);
        const onboardingRecords = await CustomerOnboardingRecord.loadAll(
            registryBucket,
            registry.customerRecordPrefix,
        );
        const tenancy = buildAccountTenancy(onboardingRecords);
        const accounts = registry.accounts ?? [];
        const collected: Array<MeteredInstance> = [];
        for (const account of accounts) {
            // eslint-disable-next-line no-await-in-loop
            const instances = await Ec2InstanceDataGathererService.readAccount(account, dimensionId);
            collected.push(...instances);
        }
        Ec2InstanceDataGathererService.logger.log(
            `Metered ${collected.length} instances across ${accounts.length} accounts`,
        );

        const runningTime: Record<string, number> = {};
        const instanceIds: Record<string, Array<string>> = {};
        collected.forEach((instance) => {
            const attributions = Ec2InstanceDataGathererService.attributeInstance(
                instance,
                tenancy[instance.accountId],
            );
            if (!attributions.length) {
                Ec2InstanceDataGathererService.logger.warn(
                    `Instance ${instance.instanceId} in account ${instance.accountId} could not be placed on an onboarded customer, leaving it off the bill`,
                );
                return;
            }
            attributions.forEach(({ customerId, share }) => {
                runningTime[customerId] = (runningTime[customerId] ?? 0) + RUNNING_TIME_INCREMENT * share;
                instanceIds[customerId] = (instanceIds[customerId] ?? []).concat(instance.instanceId);
            });
        });

        return Object.keys(runningTime)
            .sort()
            .map(
                (customerId) =>
                    new StandardMeasurementEntity({
                        businessID,
                        dimensionId,
                        metadata: {
                            instanceIds: instanceIds[customerId].sort().join(','),
                            instanceCount: instanceIds[customerId].length,
                        },
                        recordValue: runningTime[customerId],
                        customerId,
                        _measurement: UsageEntity._measurement,
                    }),
            );
    }

    /**
     * Works out which customers carry an instance's running time and how much of
     * it each of them carries. Returns an empty list when the usage cannot be
     * placed on a customer onboarded for the instance's account.
     */
    static attributeInstance(instance: MeteredInstance, tenancy?: AccountTenancy): Array<InstanceAttribution> {
        if (!tenancy || !tenancy.customerIds.length) {
            // Nobody is onboarded for this account, so nothing here is billable.
            return [];
        }
        if (tenancy.dedicatedTo) {
            // The account belongs to one customer, tags cannot move the usage
            // elsewhere and a missing tag does not make it unbillable.
            return [{ customerId: tenancy.dedicatedTo, share: 1 }];
        }
        const taggedCustomerIds = (instance.tags?.meteringCustomerId ?? '')
            .split(',')
            .map((customerId) => customerId.trim())
            .filter((customerId) => customerId.length);
        const tenants = taggedCustomerIds
            .filter((customerId, index) => taggedCustomerIds.indexOf(customerId) === index)
            .filter((customerId) => tenancy.customerIds.includes(customerId));
        if (!tenants.length) {
            return [];
        }
        const share = 1 / tenants.length;
        return tenants.map((customerId) => ({ customerId, share }));
    }

    private static async readAccount(
        account: MeteredAccount,
        dimensionId: string,
    ): Promise<Array<MeteredInstance>> {
        const creds = fromTemporaryCredentials({
            params: {
                RoleArn: account.roleArn,
                ExternalId: account.externalId ? account.externalId : undefined,
            },
            clientConfig: { region: 'us-east-1' },
        });
        const instanceList = await getInstanceWithFilters(account.region, creds, [
            { Name: 'instance-state-name', Values: ['running'] },
            { Name: 'tag-key', Values: ['meteringDimensionId'] },
        ]);
        return instanceList
            .filter((instance) => {
                const tags = instance.Tags ?? [];
                const taggedDimensionIdVal = tags.find((tag) => tag.Key === 'meteringDimensionId');
                if (!taggedDimensionIdVal) {
                    return false;
                }
                const meteringDimensionIds = taggedDimensionIdVal.Value.split(',');
                return meteringDimensionIds.includes(dimensionId);
            })
            .map((instance) => ({
                accountId: account.accountId,
                instanceId: instance.InstanceId,
                instanceType: instance.InstanceType,
                region: account.region,
                tags: (instance.Tags ?? []).reduce((acc, { Key, Value }) => {
                    acc[Key] = Value;
                    return acc;
                }, {} as Record<string, string>),
            }));
    }

    @OnQueueFailed({ name: infrastructureType.instanceRunningTime })
    jobFailure(job: Job) {
        AuditService.publishEvent({
            message: 'Failed to measure EC2 instance running time',
            data: [job],
            topic: AuditScope.ERROR,
        });
    }
}
